<?php require_once __DIR__.'/business-grid.php';$day=validDate($_GET['day']??date('Y-m-d',strtotime('tomorrow')));$selected=is_array($_GET['batches']??null)?$_GET['batches']:[];$quantities=[];$orders=query('SELECT o.*,c.name FROM biz_orders o JOIN biz_clients c ON c.id=o.client_id WHERE o.cancelled=0 AND o.day<=? AND EXISTS(SELECT 1 FROM biz_deliveries d WHERE d.batch_key=o.batch_key AND d.cancelled=0 AND d.sent=0) ORDER BY o.day,c.name',[$day])->fetchAll();
foreach($orders as $o)if(in_array($o['batch_key'],$selected,true))foreach(query('SELECT product_id,planned FROM biz_deliveries WHERE batch_key=? AND cancelled=0 AND sent=0',[$o['batch_key']])->fetchAll() as $line)$quantities[$line['product_id']]=($quantities[$line['product_id']]??0)+(int)$line['planned'];
if(($_GET['calculate']??'')==='simulate'){$quantities=[];foreach($products as $p)$quantities[$p['id']]=positiveInt($_GET['qty'][$p['id']]??0,0,100000);}
?>
<div class="toolbar no-print"><a href="/?page=biz-plan">← 주문서 관리</a><button class="button secondary" id="print-order" type="button">인쇄</button></div>
<form method="get" class="panel stack no-print"><input type="hidden" name="page" value="biz-production"><label>생산 대상 납품 (예정)일<input type="date" name="day" value="<?=$day?>" required></label><h2>미납품 주문 선택</h2><div class="biz-inline"><button type="button" class="button secondary" data-biz-check="1">모두 선택</button><button type="button" class="button secondary" data-biz-check="0">선택 해제</button></div><?php foreach($orders as $o): ?><label class="checkbox"><input name="batches[]" type="checkbox" value="<?=$o['batch_key']?>" <?=in_array($o['batch_key'],$selected,true)?'checked':''?>><?=e($o['day'].' · '.$o['name'])?><?php $descriptions=[];foreach(query('SELECT p.ko,d.planned FROM biz_deliveries d JOIN biz_products p ON p.id=d.product_id WHERE d.batch_key=? AND d.cancelled=0 AND d.sent=0',[$o['batch_key']])->fetchAll() as $line)$descriptions[]=$line['ko'].' '.$line['planned']; ?> · <?=e(implode(', ',$descriptions))?></label><?php endforeach ?><button class="button" name="calculate" value="orders">선택한 주문으로 생산량 계산</button><h2>생산량 시뮬레이션</h2><p>수량을 바꾸어 재료 소요량을 시험할 수 있습니다. 주문·납품 수량은 변경되지 않습니다.</p><?php bizQtyGrid($products,$quantities); ?><button class="button" name="calculate" value="simulate">시뮬레이션 계산</button></form>
<section class="panel"><h2><?=e($day)?> 생산 계획</h2><table><thead><tr><th>제품</th><th>생산 수량</th></tr></thead><tbody><?php $rows=[];foreach($products as $p):$q=$quantities[$p['id']]??0;if(!$q)continue;$rows[]=[...$p,'qty'=>$q]; ?><tr><td><?=e(bizKo($p))?></td><td><?=$q?></td></tr><?php endforeach ?></tbody></table><?php require __DIR__.'/business-materials.php'; ?></section>
